using System.Text;
namespace QualifyAI.Api;
public static class AutonomousAcquisitionDashboardEndpoints{public static IEndpointRouteBuilder MapAutonomousAcquisitionDashboard(this IEndpointRouteBuilder app){app.MapGet("/autonomous-acquisition",()=>Results.Content(Html(),"text/html; charset=utf-8"));return app;}static string Html()=>"""<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Autonomous Acquisition</title><style>body{font-family:Inter,Arial;margin:0;background:#0b1020;color:#e8eefc}.wrap{max-width:1200px;margin:auto;padding:32px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:16px}.card{background:#151d33;border:1px solid #26304d;border-radius:14px;padding:18px}.muted{color:#9ca9c9}button{background:#4f7cff;color:#fff;border:0;border-radius:8px;padding:10px 14px;cursor:pointer}select,input,textarea{width:100%;box-sizing:border-box;padding:10px;background:#0f1628;color:#fff;border:1px solid #34405f;border-radius:8px}.row{display:flex;gap:10px;flex-wrap:wrap}.row>*{flex:1;min-width:160px}table{width:100%;border-collapse:collapse}th,td{padding:10px;border-bottom:1px solid #26304d;text-align:left}.pill{padding:4px 8px;border-radius:99px;background:#26304d}.hidden{display:none}</style></head><body><div class='wrap'><h1>Autonomous Acquisition Agent</h1><p class='muted'>Create, configure, run and monitor autonomous customer acquisition agents.</p><div class='card'><div class='row'><input id='tenant' placeholder='Tenant ID'><button onclick='load()'>Load</button><button onclick='showCreate()'>Create Agent</button></div></div><div id='editor' class='card hidden' style='margin-top:20px'><h2 id='formTitle'>Create Agent</h2><div class='row'><input id='name' placeholder='Agent name'><select id='template'></select><input id='industry' placeholder='Industry'></div><div class='row'><input id='region' placeholder='Region'><input id='countries' placeholder='Countries, comma separated'><input id='threshold' type='number' value='90' placeholder='Minimum score'></div><div class='row'><input id='dailyDiscovery' type='number' value='50' placeholder='Daily discovery limit'><input id='dailyEmail' type='number' value='20' placeholder='Daily email limit'><input id='runTime' type='time' value='08:00'></div><div class='row'><textarea id='icp' placeholder='ICP notes / qualification instructions'></textarea></div><div class='row'><button onclick='saveAgent()'>Save Agent</button><button onclick='cancelEdit()'>Cancel</button></div></div><div class='card' style='margin-top:20px'><h2>Agents</h2><table><thead><tr><th>Name</th><th>Template</th><th>Industry</th><th>Status</th><th>Threshold</th><th></th></tr></thead><tbody id='agents'></tbody></table></div></div><script>let editing=null;async function load(){let t=tenant.value;if(!t)return;let ts=await fetch('/api/autonomous-acquisition/templates').then(r=>r.json());template.innerHTML=ts.map(x=>`<option value='${x.code}'>${x.name}</option>`).join('');let a=await fetch('/api/autonomous-acquisition/tenants/'+t+'/agents').then(r=>r.json());agents.innerHTML=a.map(x=>`<tr><td>${x.name}</td><td>${x.templateCode}</td><td>${x.industry||''}</td><td><span class='pill'>${x.status}</span></td><td>${x.minimumScore}</td><td><button onclick='editAgent(${JSON.stringify(x).replaceAll("'","&#39;")})'>Edit</button></td></tr>`).join('');window.current=a;}function showCreate(){editing=null;formTitle.textContent='Create Agent';editor.classList.remove('hidden');}function cancelEdit(){editor.classList.add('hidden');editing=null;}function editAgent(x){editing=x;formTitle.textContent='Edit Agent';name.value=x.name||'';template.value=x.templateCode||'';industry.value=x.industry||'';region.value=x.region||'';countries.value=Array.isArray(x.countries)?x.countries.join(','):'';threshold.value=x.minimumScore||90;dailyDiscovery.value=x.dailyDiscoveryLimit||50;dailyEmail.value=x.dailyEmailLimit||20;runTime.value=x.runTimeUtc||'08:00';icp.value=x.icpNotes||'';editor.classList.remove('hidden');}async function saveAgent(){let t=tenant.value;if(!t)return;let body={name:name.value,templateCode:template.value,industry:industry.value,region:region.value,countriesJson:JSON.stringify(countries.value.split(',').map(x=>x.trim()).filter(Boolean)),minimumScore:+threshold.value,dailyDiscoveryLimit:+dailyDiscovery.value,dailyEmailLimit:+dailyEmail.value,runTimeUtc:runTime.value,icpNotes:icp.value};let url='/api/autonomous-acquisition/tenants/'+t+'/agents'+(editing?'/'+editing.id:'');let method=editing?'PUT':'POST';let r=await fetch(url,{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!r.ok){alert(await r.text());return;}cancelEdit();load();}</script></body></html>""";}
